const incomingItems = $input.all();

// 1. Define el ORDEN EXACTO que quieres en la salida.
// He reordenado esta lista para que coincida con tu JSON de ejemplo.
const orderedColumnIds = [
  'personas__1',              // Personas
  'text8',                    // Empresa
  'estado__1',                // Industria
  'text_mksx2nnx',            // Id cuenta publicitaria
  'board_relation_mktnkez8',  // Asignación de Estrategas
  'contact_phone',            // Teléfono
  'contact_email'             // E-mail
];

const formattedItems = incomingItems.map(item => {
  const mondayItem = item.json;

  // 2. Construye el array 'column_values' en el orden definido.
  const orderedColumns = orderedColumnIds.map(columnId => {
    // 3. Por cada ID en nuestro orden, busca la columna correspondiente en los datos de entrada.
    const foundColumn = mondayItem.column_values.find(c => c.id === columnId);

    // Si la columna no existe en este item, no la añade.
    if (!foundColumn) {
      return null;
    }

    // 4. Procesa la columna encontrada (lógica que ya tenías).
    const titulo = foundColumn.column.title;
    const newColumn = {
      id: titulo,
      text: foundColumn.text,
    };

    if (titulo === 'Personas') {
      newColumn.value = foundColumn.value;
    }
    if (titulo === 'Asignación de Estrategas') {
      newColumn.value = foundColumn.value;
    }
    if (titulo === 'Industria') {
      newColumn.tags = foundColumn.column.settings_str;
    }

    return newColumn;
  }).filter(Boolean); // Elimina cualquier valor 'null' si una columna no fue encontrada.

  const desiredFormat = {
    "data": {
      "id": mondayItem.id,
      "name": mondayItem.name,
      "column_values": orderedColumns // Usa el nuevo array ordenado.
    }
  };

  return {
    json: desiredFormat
  };
});

return formattedItems;

// --- 1. Obtener los datos de entrada ---
const primerJson = $('Aggregate2').first().json['primer-json'];
const segundoJson = $input.first().json['segundo-json'];

// --- 2. Crear un índice de búsqueda rápida a partir del segundo JSON ---
const idsSlackExistentes = new Set();
const nombresExistentes = new Set();

for (const item of segundoJson) {
  if (item['ID-slack']) {
    idsSlackExistentes.add(item['ID-slack']);
  }
  if (item.nombre) {
    nombresExistentes.add(item.nombre);
  }
}

// --- 3. Inicializar los arrays para las dos salidas ---
const itemsSinCoincidencia = []; // Para la primera salida (Output 0)
const itemsConCoincidencia = []; // Para la segunda salida (Output 1)

// --- 4. Clasificar cada item del primer JSON ---
for (const itemPrimerJson of primerJson) {

  // Extraemos el nombre y el ID de Slack
  const nombrePrimerJson = itemPrimerJson.name;
  const columnaSlack = itemPrimerJson.column_values.find(col => col.id === 'text_mktwg0h3');
  const idSlackPrimerJson = columnaSlack ? columnaSlack.text : null;

  // Verificamos si existe en el segundo JSON
  const nombreExiste = nombresExistentes.has(nombrePrimerJson);
  const idSlackExiste = idSlackPrimerJson ? idsSlackExistentes.has(idSlackPrimerJson) : false;

  // Si hay alguna coincidencia (por nombre O por ID de Slack)...
  if (nombreExiste || idSlackExiste) {
    // ...lo añadimos a la lista de coincidencias.
    itemsConCoincidencia.push(itemPrimerJson);
  } else {
    // ...de lo contrario, lo añadimos a la lista de NO coincidencias.
    itemsSinCoincidencia.push(itemPrimerJson);
  }
}

// --- 5. Devolver los dos resultados para las dos salidas ---
// El primer objeto del array va a la primera salida, el segundo objeto a la segunda, y así sucesivamente.
return [
  {
    json: {
      // Este objeto JSON completo irá a la salida 0
      items_sin_coincidencia: itemsSinCoincidencia
    }
  },
  {
    json: {
      // Este objeto JSON completo irá a la salida 1
      items_con_coincidencia: itemsConCoincidencia
    }
  }
];

